class Twitter {
    int timestamp;
    unordered_map<int, vector<pair<int,int>>> tweets;
    unordered_map<int, unordered_set<int>> following;
public:
    Twitter() : timestamp(0) {}

    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({timestamp++, tweetId});
    }

    vector<int> getNewsFeed(int userId) {
        priority_queue<pair<int, pair<int,int>>> pq;

        unordered_set<int> followees;
        auto it = following.find(userId);
        if (it != following.end()) {
            followees = it->second;
        }
        followees.insert(userId);

        for (int f : followees) {
            auto tit = tweets.find(f);
            if (tit != tweets.end() && !tit->second.empty()) {
                int idx = tit->second.size() - 1;
                pq.push({tit->second[idx].first, {f, idx}});
            }
        }

        vector<int> result;
        while (!pq.empty() && result.size() < 10) {
            auto top = pq.top();
            pq.pop();
            int uid = top.second.first;
            int idx = top.second.second;
            result.push_back(tweets[uid][idx].second);
            if (idx > 0) {
                idx--;
                pq.push({tweets[uid][idx].first, {uid, idx}});
            }
        }
        return result;
    }

    void follow(int followerId, int followeeId) {
        following[followerId].insert(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        auto it = following.find(followerId);
        if (it != following.end()) {
            it->second.erase(followeeId);
        }
    }
};
